        && state_partition.principal_id == request.principal_id
        && state_partition.agent_id == request.agent_id
        && state_partition.cell_id == request.cell_id
        && state_partition.run_id != request.source_run_id
        && !checkpoint_digest.is_zero()
        && matches!(self.snapshot.receipts.last().map(|receipt| &receipt.observation),
            Some(LearningIterationObservationV1::Selection { selection_digest: expected, .. }) if selection_digest == expected)
        && !committed_step_receipt.is_zero()
        && !state_cutover_receipt.is_zero()
}
LearningIterationObservationV1::RetainedModelNextUse {
    retained_bundle,
    state_partition,
    checkpoint_digest,
    selection_digest,
    committed_step_receipt,
    task_owner_publication,
} => {
    next_task_bundle == Some(*retained_bundle)
        && *retained_bundle == request.selected_bundle.digest()?
        && state_partition.principal_id == request.principal_id
        && state_partition.agent_id == request.agent_id
        && state_partition.cell_id == request.cell_id
        && state_partition.run_id != request.source_run_id
        && !checkpoint_digest.is_zero()
        && matches!(self.snapshot.receipts.last().map(|receipt| &receipt.observation),
            Some(LearningIterationObservationV1::Selection { selection_digest: expected, .. }) if selection_digest == expected)
        && !committed_step_receipt.is_zero()
        && !task_owner_publication.is_zero()
}

impl LearningIterationObservationV1 {
    pub const fn stage(&self) -> LearningIterationStageV1 {
        match self {
            Self::Experience { .. } => LearningIterationStageV1::Experience,
            Self::Dataset { .. } => LearningIterationStageV1::Dataset,
            Self::Training { .. } | Self::TrainingNoUpdateV2(_) => {
                LearningIterationStageV1::Training
            }
            Self::Evaluation { .. } => LearningIterationStageV1::Evaluation,
            Self::Proposal { .. } => LearningIterationStageV1::Proposal,
            Self::Selection { .. } | Self::LocalDecisionV2(_) => {
                LearningIterationStageV1::Selection
            }
            Self::NextUse { .. } | Self::RetainedModelNextUse { .. } => {
                LearningIterationStageV1::NextUse
            }
        }
    }
}

impl LearningIterationOwnersV1 {
    pub fn owner(&self, stage: LearningIterationStageV1) -> &StableId {
        match stage {
            LearningIterationStageV1::Experience => &self.experience,
            LearningIterationStageV1::Dataset => &self.dataset,
            LearningIterationStageV1::Training => &self.trainer,
            LearningIterationStageV1::Evaluation => &self.evaluator,
            LearningIterationStageV1::Proposal => &self.proposal,
            LearningIterationStageV1::Selection => &self.selector,
            LearningIterationStageV1::NextUse => &self.next_use_observer,
        }
    }

    }

    pub fn validate_request(
        &self,
        request: &LearningIterationRequestV1,
        owners: &LearningIterationOwnersV1,
    ) -> Result<(), LearningIterationError> {
        if initial_digest(request, owners)? != self.initial_head {
            return Err(LearningIterationError::UpdateScopeMismatch);
        }
        Ok(())
    }

    /// Check before advancing to evaluation or publishing another checkpoint.
    pub fn validate_observation(
        &self,
        observation: &LearningIterationObservationV1,
    ) -> Result<(), LearningIterationError> {
        if let LearningIterationObservationV1::TrainingNoUpdateV2(outcome) = observation
            && outcome.update_rule != self.update_rule
        {
            return Err(LearningIterationError::UpdateScopeMismatch);
        }
        if let LearningIterationObservationV1::Training { candidate, .. } = observation {
            let mut preserved = candidate.components.clone();
            // These changed components remain subject to the existing tensor,
            // evaluation, compatibility and publication owners.
            preserved.heads = self.components.heads;
            preserved.calibration = self.components.calibration;
            preserved.composition = self.components.composition;
            match self.scope {
                LearningUpdateScopeV2::Cell => {
                    preserved.cell_adapter = self.components.cell_adapter;
                }
                LearningUpdateScopeV2::Organ => {
                    preserved.organ_adapter = self.components.organ_adapter;
                }
                LearningUpdateScopeV2::BaseRelease => {
                    return Err(LearningIterationError::SlowReleaseRequired);
                }
            }
            if preserved != self.components
                || candidate
                    .training_lineage
                    .as_ref()
                    .map(|lineage| lineage.update_rule)
                    != Some(self.update_rule)
            {
                return Err(LearningIterationError::UpdateScopeMismatch);
            }
        }
        Ok(())
    }

    /// Restoring a later cut rechecks every original candidate, even when its
    /// evaluator eventually returned NoUpdate. That result cannot widen scope.
    pub fn validate_snapshot(
        &self,
        snapshot: &LearningIterationSnapshotV1,
    ) -> Result<(), LearningIterationError> {
        self.validate_request(&snapshot.request, &snapshot.owners)?;
        for receipt in &snapshot.receipts {
            self.validate_observation(&receipt.observation)?;
        }
        Ok(())
    }
}

