mod tests;

pub(crate) fn receipt_digest(
    receipt: &LearningIterationReceiptV1,
) -> Result<Digest32, LearningIterationError> {
    learning_iteration_receipt_signing_bytes_v1(receipt).map(|bytes| Digest32::of_bytes(&bytes))
}

/// Complete canonical payload for the existing learning-evidence signer.
pub fn learning_iteration_receipt_signing_bytes_v1(
    receipt: &LearningIterationReceiptV1,
) -> Result<Vec<u8>, LearningIterationError> {
    // Historical observations retain their exact signing payload. Local policy
    // is an explicit new namespace, never a reinterpretation of V1 Selection.
    let mut bytes = if matches!(
        receipt.observation,
        LearningIterationObservationV1::LocalDecisionV2(_)
    ) {
        b"hepta.learning.iteration-local-decision.v2\0".to_vec()
    } else {
        b"hepta.learning.iteration-observation.v1\0".to_vec()
    };
    append_id(&mut bytes, &receipt.operation_id);
    bytes.extend_from_slice(receipt.predecessor.as_array());
    append_id(&mut bytes, &receipt.actor_id);
    bytes.extend_from_slice(receipt.evidence_digest.as_array());
    bytes.extend_from_slice(&receipt.observed_unix_seconds.to_be_bytes());

fn no_update_keeps_baseline_and_replays_selection_and_actual_next_use() {
    for stage_count in [3, 4] {
        let mut coordinator =
            LearningIterationCoordinatorV1::new(request(), owners()).fixture("coordinator");
        for _ in 0..stage_count {
            coordinator
                .record(receipt(&coordinator), 20)
                .fixture("stage");
        }
        let mut decision = receipt(&coordinator);
        match &mut decision.observation {
            LearningIterationObservationV1::Evaluation { disposition, .. } => {
                *disposition = LearningEvaluationDispositionV1::NoUpdate
            }
            LearningIterationObservationV1::Proposal { disposition, .. } => {
                *disposition = LearningProposalDispositionV1::NoAdmissibleUpdate
            }
            _ => panic!("wrong test stage"),
        }
        coordinator.record(decision, 20).fixture("no update");
        assert_eq!(
            coordinator.disposition(),
            LearningIterationDispositionV1::NoUpdate
        );
        let original_bundle = coordinator.snapshot().request.selected_bundle.clone();
        assert_eq!(coordinator.next_task_bundle(), Some(&original_bundle));
        let rejected = coordinator
            .candidate()
            .fixture("candidate")
            .digest()
            .fixture("digest");
        for stage in [
            LearningIterationStageV1::Selection,
            LearningIterationStageV1::NextUse,
        ] {
            coordinator =
                LearningIterationCoordinatorV1::from_snapshot(coordinator.snapshot().clone())
                    .fixture("reopen pending no update");
            assert_eq!(coordinator.next_stage(), Some(stage));
            assert_eq!(
                coordinator.disposition(),
                LearningIterationDispositionV1::NoUpdate
            );
            let before = coordinator.snapshot().clone();
            let actual = receipt(&coordinator);
            let mut wrong = actual.clone();
            match &mut wrong.observation {
                LearningIterationObservationV1::Selection {
                    candidate_bundle, ..
                }
                | LearningIterationObservationV1::NextUse {
                    candidate_bundle, ..
                } => {
                    *candidate_bundle = rejected;
                }
                LearningIterationObservationV1::RetainedModelNextUse {
                    retained_bundle, ..
                } => {
                    *retained_bundle = rejected;
                }
                _ => panic!("wrong test stage"),
            }
            assert_eq!(
                coordinator.record(wrong, 20),
                Err(LearningIterationError::ContextMismatch)
            );
            assert_eq!(coordinator.snapshot(), &before);
            coordinator
                .record(actual.clone(), 20)
                .fixture("retained baseline");
            let committed = coordinator.snapshot().clone();
            assert_eq!(coordinator.record(actual, 200), Ok(committed.head_digest));
            coordinator = LearningIterationCoordinatorV1::from_snapshot(committed.clone())
                .fixture("reopen committed");
            assert_eq!(coordinator.snapshot(), &committed);
        }
        assert_eq!(coordinator.next_stage(), None);
        assert_eq!(
            coordinator.disposition(),
            LearningIterationDispositionV1::UsedByNextTask
        );
        assert_eq!(coordinator.next_task_bundle(), Some(&original_bundle));
    }
}

fn trainer_no_update_requires_selection_and_real_retained_use_without_candidate_or_evaluation() {
    let mut coordinator = dataset_cut();
    let scope = scope(&coordinator);
    let observed = unchanged(&coordinator);
    scope
        .validate_observation(&observed.observation)
        .fixture("frozen outcome");
    coordinator
        .record(observed, 20)
        .fixture("trainer no update");
    assert_eq!(coordinator.candidate(), None);
    assert_eq!(
        coordinator.disposition(),
        LearningIterationDispositionV1::NoUpdate
    );
    assert_eq!(
        coordinator.next_stage(),
        Some(LearningIterationStageV1::Selection)
    );
    assert_eq!(
        coordinator.next_task_bundle(),
        Some(&coordinator.snapshot().request.selected_bundle)
    );
    let pending = coordinator.snapshot().clone();
    let mut wrong_owner = receipt(&coordinator);
    wrong_owner.actor_id = pending.owners.trainer.clone();
    assert_eq!(
        coordinator.record(wrong_owner, 20),
        Err(LearningIterationError::WrongOwner)
    );
    assert_eq!(coordinator.snapshot(), &pending);
    coordinator
        .record(receipt(&coordinator), 20)
        .fixture("independent selection");
    assert_eq!(
        coordinator.disposition(),
        LearningIterationDispositionV1::NoUpdate
    );
    assert_eq!(
        coordinator.next_stage(),
        Some(LearningIterationStageV1::NextUse)
    );
    let before = coordinator.snapshot().clone();
